package com.nhpms.identity.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="refresh_tokens",schema="iam") public class RefreshToken { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="refresh_token_id") UUID id; @Column(name="user_id",nullable=false) UUID userId; @Column(name="token_hash",nullable=false,unique=true) String tokenHash; @Column(name="expires_at",nullable=false) Instant expiresAt; @Column(name="revoked_at") Instant revokedAt; @Column(name="created_at",nullable=false) Instant createdAt=Instant.now(); @Column(name="ip_address") String ipAddress; @Column(name="user_agent") String userAgent; public UUID getId(){return id;} public UUID getUserId(){return userId;} public void setUserId(UUID v){userId=v;} public String getTokenHash(){return tokenHash;} public void setTokenHash(String v){tokenHash=v;} public Instant getExpiresAt(){return expiresAt;} public void setExpiresAt(Instant v){expiresAt=v;} public Instant getRevokedAt(){return revokedAt;} public void setRevokedAt(Instant v){revokedAt=v;} public void setIpAddress(String v){ipAddress=v;} public void setUserAgent(String v){userAgent=v;} }
